private ContentHandler createHandlerInner() {
    if (type == HANDLER_TYPE.BODY) {
        return new BodyContentHandler(new WriteOutContentHandler(new ToTextContentHandler(), writeLimit, throwOnWriteLimitReached, parseContext));
    } else if (type == HANDLER_TYPE.IGNORE) {
        return new NoOpContentHandler();
    }
    ContentHandler formatHandler = getFormatHandler();
    if (writeLimit < 0) {
        return formatHandler;
    }
    return new WriteOutContentHandler(formatHandler, writeLimit, throwOnWriteLimitReached, parseContext);
}
